    {
        m_hint = aHint;
    }

    const BOX2I ViewBBox() const override;
    std::vector<int> ViewGetLayers() const override;
    void ViewDraw( int aLayer, KIGFX::VIEW* aView ) const override;

protected:
    VECTOR2I m_pos;
    wxString m_status;
    wxString m_hint;
};



