    while( layerStackupId < static_cast<int>( aLayerList.size() ) && !layerFound )
    {
        if( aLayerList.at( layerStackupId )->GetBrdLayerId() != aPcbLayerId )
            ++layerStackupId;
        else
            layerFound = true;
    }

    if( !layerFound )
        return -1;

    return layerStackupId;
}


