            if( lenIt != totalLen.end() && lenIt->second > 0 )
                item->SetAvgImpedance( static_cast<int>( weightedSum[netCode] / lenIt->second ) );
        }
    }
    catch( const std::exception& )
    {
        // Defensive: a malformed stackup or track shouldn't take down board loading.
        // Avg Z₀ stays at 0 for the affected nets.
    }

    return results;
}

