export const meta = {
  name: 'in-review-test-procedures',
  description: 'Produce code-grounded manual test procedures for the 5 In-Review Zeo 0.3.0 tickets, then adversarially verify each against the source.',
  phases: [
    { title: 'Read', detail: 'one reader per ticket extracts the real implementation + test steps' },
    { title: 'Verify', detail: 'adversarially check each procedure against the code' },
  ],
}

const ROOT = '/Users/gmp/workspaces/zeodotdev/zeo/src/zeo'

const PROC_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['ticket', 'feature', 'whatItDoes', 'triggerSurface', 'prerequisites', 'steps', 'expectedResult', 'literalStrings', 'caveats', 'filesRead'],
  properties: {
    ticket: { type: 'string' },
    feature: { type: 'string', description: 'one-line name' },
    whatItDoes: { type: 'string', description: '2-3 sentences on the implemented behavior, grounded in code' },
    triggerSurface: { type: 'string', description: 'exactly where/when the behavior appears in the UI, and what code path drives it' },
    prerequisites: { type: 'array', items: { type: 'string' } },
    steps: { type: 'array', items: { type: 'string' }, description: 'precise click-by-click steps' },
    expectedResult: { type: 'string', description: 'what the user should observe if it works' },
    literalStrings: { type: 'array', items: { type: 'string' }, description: 'exact format strings / labels the code emits, copied verbatim from source' },
    caveats: { type: 'array', items: { type: 'string' }, description: 'known limitations, partial implementation, things that will NOT work' },
    filesRead: { type: 'array', items: { type: 'string' } },
  },
}

const VERDICT_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['ticket', 'stepsReproducible', 'problems', 'correctedNotes'],
  properties: {
    ticket: { type: 'string' },
    stepsReproducible: { type: 'boolean', description: 'true if a user following the steps would actually observe the expected result given the code' },
    problems: { type: 'array', items: { type: 'string' }, description: 'specific steps that will not reproduce, with the code reason' },
    correctedNotes: { type: 'string', description: 'corrections to make the procedure accurate, or empty if none' },
  },
}

const TICKETS = [
  {
    key: 'MOON-1429 (A4)',
    name: 'Z₀ display in PNS router status bar / message panel',
    pointers: [
      `${ROOT}/pcbnew/router/router_tool.cpp — buildImpedanceStatus(), and its use inside UpdateMessagePanel() and the drag-mode ROUTER_STATUS_VIEW_ITEM blocks`,
      `${ROOT}/pcbnew/router/router_tool.h`,
      `${ROOT}/pcbnew/board_stackup_manager/impedance_calculator.cpp/.h`,
    ],
  },
  {
    key: 'MOON-1424 (B1a)',
    name: 'Real-time DRC — TRACK_WIDTH_CONSTRAINT during routing',
    pointers: [
      `${ROOT}/pcbnew/router/router_tool.cpp — buildDrcViolationDetail() (TRACK_WIDTH branch), and where it is surfaced (UpdateMessagePanel + drag overlay)`,
      `${ROOT}/pcbnew/router/pns_node.h — PNS::CONSTRAINT m_ViolationDetail field`,
    ],
  },
  {
    key: 'MOON-1431 (B1b)',
    name: 'Real-time DRC — VIA_DIAMETER + DISALLOW (TRACK_ANGLE/VIA_COUNT deferred)',
    pointers: [
      `${ROOT}/pcbnew/router/router_tool.cpp — buildDrcViolationDetail() VIA_DIAMETER and DISALLOW branches; note which of the 4 planned constraints are actually implemented vs deferred`,
    ],
  },
  {
    key: 'MOON-1425 (B2)',
    name: 'Schematic-side diff-pair declaration via context menu',
    pointers: [
      `${ROOT}/eeschema/tools/sch_edit_tool.cpp — MarkAsDiffPair() handler and the selToolMenu entry / markAsDiffPairCondition`,
      `${ROOT}/eeschema/tools/sch_actions.cpp — markAsDiffPair action (FriendlyName)`,
      `${ROOT}/common/project/project_file.cpp — AddCrossBoardDiffPair / RemoveCrossBoardDiffPair and how cross_board_diff_pairs serializes to .kicad_pro`,
    ],
  },
  {
    key: 'MOON-1427 (C2d)',
    name: 'Variant-aware DRC consistency + discoverability polish',
    pointers: [
      `${ROOT}/pcbnew/pcb_edit_frame.cpp — UpdateTitle() variant suffix`,
      `${ROOT}/eeschema/sch_edit_frame.cpp — title variant suffix`,
      `${ROOT}/pcbnew/toolbars_pcb_editor.cpp + ${ROOT}/eeschema/toolbars_sch_editor.cpp — SetCurrentVariant calls UpdateTitle/updateTitle`,
      `Determine which of the 3 planned C2d parts actually landed: (1) variant-consistency DRC check in drc_test_provider_schematic_parity.cpp, (2) status/title indicator, (3) Tools>Variants menu promotion. Be explicit about which are NOT implemented.`,
    ],
