55	    // Walk towards a side and accumulate dielectric height and weighted-average Dk
56	    // until the next copper layer.  Returns {0, 0} on failure.  Height in metres.
57	    std::pair<double, double> collectDielectricToReference(
58	            const std::vector<BOARD_STACKUP_ITEM*>& aLayers, int aSignalIdx, int aDirection )
59	    {
60	        double totalThicknessIU = 0.0;
61	        double weightedDk = 0.0;
62	
63	        for( int i = aSignalIdx + aDirection; i >= 0 && i < (int) aLayers.size(); i += aDirection )
64	        {
65	            BOARD_STACKUP_ITEM* item = aLayers[i];
66	
67	            if( !item || !item->IsEnabled() )
68	                continue;
69	
70	            if( item->GetType() == BS_ITEM_TYPE_COPPER )
71	                break;
72	
73	            if( item->GetType() != BS_ITEM_TYPE_DIELECTRIC )
74	                continue;
75	
76	            const int t = item->GetThickness();
77	
78	            if( t <= 0 )
79	                continue;
80	
81	            totalThicknessIU += t;
82	            weightedDk += t * item->GetEpsilonR();
83	        }
84	
85	        if( totalThicknessIU <= 0 )
86	            return { 0.0, 0.0 };
87	
88	        return { totalThicknessIU / 1e9, weightedDk / totalThicknessIU };
89	    }
