19	 */
20	
21	#include "impedance_calculator.h"
22	
23	#include <board.h>
24	#include <board_design_settings.h>
25	#include <board_stackup_manager/board_stackup.h>
26	#include <transline_calculations/microstrip.h>
27	#include <transline_calculations/stripline.h>
28	#include <transline_calculations/units_scales.h>
29	#include <trace_helpers.h>
30	#include <wx/log.h>
31	
32	static const wxChar IMPEDANCE_TRACE[] = wxT( "IMPEDANCE" );
33	
34	namespace
35	{
36	    constexpr double COPPER_RHO = 1.72e-8;  // Ω·m at 20 °C — matches tuning profile dialog
37	
38	
39	    int findStackupCopperIndex( const std::vector<BOARD_STACKUP_ITEM*>& aLayers, PCB_LAYER_ID aLayer )
40	    {
41	        for( size_t i = 0; i < aLayers.size(); ++i )
42	        {
43	            BOARD_STACKUP_ITEM* item = aLayers[i];
44	
45	            if( item && item->IsEnabled() && item->GetType() == BS_ITEM_TYPE_COPPER
46	                && item->GetBrdLayerId() == aLayer )
47	            {
48	                return static_cast<int>( i );
49	            }
50	        }
51	
52	        return -1;
53	    }
54	
55	
56	    /// Result of walking the dielectric stack from a signal layer to its reference plane.
57	    struct DIELECTRIC_SPAN
58	    {
59	        double heightM = 0.0;   ///< total dielectric height, metres
60	        double dk      = 0.0;   ///< thickness-weighted average dielectric constant (εr)
61	        double df      = 0.0;   ///< thickness-weighted average loss tangent (tan δ)
62	
63	        bool valid() const { return heightM > 0.0 && dk > 0.0; }
64	    };
65	
66	
67	    // Walk towards a side and accumulate dielectric height + thickness-weighted Dk/Df until
68	    // the next copper layer.  Iterates every dielectric SUBLAYER (a single dielectric region
69	    // may hold multiple sublayers with distinct Dk/Df in microwave stackups), so the average
70	    // reflects the true composite rather than only sublayer 0.
71	    DIELECTRIC_SPAN collectDielectricToReference(
72	            const std::vector<BOARD_STACKUP_ITEM*>& aLayers, int aSignalIdx, int aDirection )
73	    {
74	        double totalThicknessIU = 0.0;
75	        double weightedDk        = 0.0;
76	        double weightedDf        = 0.0;
77	
78	        for( int i = aSignalIdx + aDirection; i >= 0 && i < (int) aLayers.size(); i += aDirection )
79	        {
80	            BOARD_STACKUP_ITEM* item = aLayers[i];
81	
82	            if( !item || !item->IsEnabled() )
83	                continue;
84	
85	            if( item->GetType() == BS_ITEM_TYPE_COPPER )
86	                break;
87	
88	            if( item->GetType() != BS_ITEM_TYPE_DIELECTRIC )
89	                continue;
90	
91	            for( int sub = 0; sub < item->GetSublayersCount(); ++sub )
92	            {
93	                const int t = item->GetThickness( sub );
94	
95	                if( t <= 0 )
96	                    continue;
97	
98	                totalThicknessIU += t;
99	                weightedDk += t * item->GetEpsilonR( sub );
100	                weightedDf += t * item->GetLossTangent( sub );
101	            }
102	        }
103	
104	        if( totalThicknessIU <= 0 )
105	            return {};
106	
107	        return { totalThicknessIU / 1e9, weightedDk / totalThicknessIU,
108	                 weightedDf / totalThicknessIU };
109	    }
110	
111	
112	    int analyseMicrostrip( double aWidthM, double aSignalThicknessM, double aHeightM, double aDk,
113	                           double aDf, const IMPEDANCE_PARAMS& aParams )
114	    {
115	        const double rho = aParams.conductorRho > 0.0 ? aParams.conductorRho : 1.72e-8;
116	
117	        MICROSTRIP ms;
118	        ms.SetParameter( TRANSLINE_PARAMETERS::PHYS_WIDTH, aWidthM );
119	        ms.SetParameter( TRANSLINE_PARAMETERS::T, aSignalThicknessM );
120	        ms.SetParameter( TRANSLINE_PARAMETERS::H, aHeightM );
121	        ms.SetParameter( TRANSLINE_PARAMETERS::H_T, 1e6 );  // free air above; effectively infinite
122	        ms.SetParameter( TRANSLINE_PARAMETERS::EPSILONR, aDk );
123	        ms.SetParameter( TRANSLINE_PARAMETERS::MUR, 1.0 );
124	        ms.SetParameter( TRANSLINE_PARAMETERS::MURC, 1.0 );
125	        ms.SetParameter( TRANSLINE_PARAMETERS::FREQUENCY, aParams.frequencyHz );
126	        ms.SetParameter( TRANSLINE_PARAMETERS::TAND, aDf );
127	        ms.SetParameter( TRANSLINE_PARAMETERS::ROUGH, aParams.roughnessM );
128	        ms.SetParameter( TRANSLINE_PARAMETERS::SIGMA, 1.0 / rho );
129	        ms.SetParameter( TRANSLINE_PARAMETERS::PHYS_LEN, 1.0 );
130	        ms.SetParameter( TRANSLINE_PARAMETERS::ANG_L, 1.0 );
131	
132	        ms.Analyse();
133	
134	        auto& results = ms.GetAnalysisResults();
135	        auto  zIt = results.find( TRANSLINE_PARAMETERS::Z0 );
136	
137	        if( zIt == results.end() || zIt->second.second != TRANSLINE_STATUS::OK )
138	            return 0;
139	
140	        return static_cast<int>( zIt->second.first + 0.5 );
141	    }
142	
143	
144	    int analyseStripline( double aWidthM, double aSignalThicknessM, double aTopH, double aBotH,
145	                          double aDk, double aDf, const IMPEDANCE_PARAMS& aParams )
146	    {
147	        const double rho = aParams.conductorRho > 0.0 ? aParams.conductorRho : 1.72e-8;
148	
149	        // STRIPLINE's m_parameters map does NOT include MUR or ROUGH — SetParameter uses
150	        // unordered_map::at() and throws std::out_of_range if we pass unsupported keys.
151	        // Roughness therefore can't be modelled for striplines yet (tracked as Phase 2).
152	        STRIPLINE sl;
153	        sl.SetParameter( TRANSLINE_PARAMETERS::PHYS_WIDTH, aWidthM );
154	        sl.SetParameter( TRANSLINE_PARAMETERS::T, aSignalThicknessM );
155	        sl.SetParameter( TRANSLINE_PARAMETERS::H, aTopH + aBotH + aSignalThicknessM );
156	        sl.SetParameter( TRANSLINE_PARAMETERS::STRIPLINE_A, aTopH );
157	        sl.SetParameter( TRANSLINE_PARAMETERS::EPSILONR, aDk );
158	        sl.SetParameter( TRANSLINE_PARAMETERS::MURC, 1.0 );
159	        sl.SetParameter( TRANSLINE_PARAMETERS::FREQUENCY, aParams.frequencyHz );
160	        sl.SetParameter( TRANSLINE_PARAMETERS::TAND, aDf );
161	        sl.SetParameter( TRANSLINE_PARAMETERS::SIGMA, 1.0 / rho );
162	        sl.SetParameter( TRANSLINE_PARAMETERS::PHYS_LEN, 1.0 );
163	        sl.SetParameter( TRANSLINE_PARAMETERS::ANG_L, 1.0 );
164	
165	        sl.Analyse();
166	
167	        auto& results = sl.GetAnalysisResults();
168	        auto  zIt = results.find( TRANSLINE_PARAMETERS::Z0 );
169	
170	        if( zIt == results.end() || zIt->second.second != TRANSLINE_STATUS::OK )
171	            return 0;
172	
173	        return static_cast<int>( zIt->second.first + 0.5 );
174	    }
175	
176	
177	    // Djordjevic-Sarkar (wideband Debye) causal dielectric dispersion.  Given the datasheet
178	    // (dk0, df0) specified at fMeasHz, returns the causal (Dk, Df) at fTargetHz.  Returns the
179	    // inputs unchanged when target == measurement frequency or inputs are degenerate, so the
180	    // default 1 GHz/1 GHz configuration reproduces the non-dispersive result exactly.
181	    //
182	    // ε(ω) = ε∞ + (Δε / ln(ω2/ω1)) · ln[(ω2 + jω)/(ω1 + jω)]
183	    //   real:  ε'(ω)  = ε∞ + (Δε / 2ln(ω2/ω1)) · ln[(ω2²+ω²)/(ω1²+ω²)]
184	    //   imag:  ε''(ω) = (Δε / ln(ω2/ω1)) · [atan(ω/ω1) − atan(ω/ω2)]
185	    // ε∞ and Δε are solved so the model reproduces (dk0, df0) at ω0.
186	    // Ref: Djordjevic et al., "Wideband Frequency-Domain Characterization of FR-4 and
187	    // Time-Domain Causality", IEEE Trans. EMC 43(4), 2001. Transition band 1 kHz – 1 THz
188	    // (matches HFSS / Altium wideband-Debye defaults).
189	    std::pair<double, double> djordjevicSarkar( double dk0, double df0, double fMeasHz,
190	                                                double fTargetHz )
191	    {
192	        constexpr double F_LOW  = 1.0e3;     // lower transition frequency, Hz
193	        constexpr double F_HIGH = 1.0e12;    // upper transition frequency, Hz
194	
195	        if( dk0 <= 0.0 || df0 <= 0.0 || fMeasHz <= 0.0 || fTargetHz <= 0.0
196	            || fTargetHz == fMeasHz )
197	        {
198	            return { dk0, df0 };
199	        }
200	
201	        const double w1 = 2.0 * M_PI * F_LOW;
202	        const double w2 = 2.0 * M_PI * F_HIGH;
203	        const double w0 = 2.0 * M_PI * fMeasHz;
204	        const double w  = 2.0 * M_PI * fTargetHz;
205	
206	        const double L           = std::log( w2 / w1 );
207	        const double atanSpread0 = std::atan( w0 / w1 ) - std::atan( w0 / w2 );
208	
209	        if( L <= 0.0 || atanSpread0 <= 0.0 )
210	            return { dk0, df0 };
211	
212	        // Solve Δε and ε∞ from the single (dk0, df0) measurement.
213	        const double epsImag0 = dk0 * df0;                    // ε''(ω0)
214	        const double deltaEps = epsImag0 * L / atanSpread0;
215	        const double epsInf   = dk0 - ( deltaEps / ( 2.0 * L ) )
216	                                          * std::log( ( w2 * w2 + w0 * w0 ) / ( w1 * w1 + w0 * w0 ) );
217	
218	        // Evaluate at the target frequency.
219	        const double dk = epsInf + ( deltaEps / ( 2.0 * L ) )
220	                                       * std::log( ( w2 * w2 + w * w ) / ( w1 * w1 + w * w ) );
221	        const double epsImag = ( deltaEps / L ) * ( std::atan( w / w1 ) - std::atan( w / w2 ) );
222	
223	        if( dk <= 0.0 )
224	            return { dk0, df0 };
225	
226	        const double df = epsImag / dk;
227	
228	        return { dk, df > 0.0 ? df : df0 };
229	    }
230	}
231	
232	
233	int IMPEDANCE_CALCULATOR::ComputeOhms( BOARD* aBoard, PCB_LAYER_ID aLayer, int aWidthIU )
234	{
235	    if( !aBoard )
236	        return 0;
237	
238	    // Pull the board's signal-integrity analysis parameters (frequency, conductor
239	    // properties) so the computation reflects the user's configured settings rather than
240	    // hardcoded defaults.
241	    const BOARD_DESIGN_SETTINGS& bds = aBoard->GetDesignSettings();
242	
243	    IMPEDANCE_PARAMS params;
244	    params.frequencyHz         = bds.m_SI_ReferenceFrequency > 0.0 ? bds.m_SI_ReferenceFrequency : 1.0e9;
245	    params.dkMeasurementFreqHz = bds.m_SI_DkMeasurementFrequency > 0.0 ? bds.m_SI_DkMeasurementFrequency : 1.0e9;
246	    params.conductorRho        = bds.m_SI_ConductorResistivity > 0.0 ? bds.m_SI_ConductorResistivity : 1.72e-8;
247	    params.roughnessM          = bds.m_SI_ConductorRoughness >= 0.0 ? bds.m_SI_ConductorRoughness : 0.0;
248	
249	    SetParams( params );
250	
251	    const BOARD_STACKUP stackup = aBoard->GetStackupOrDefault();
252	    return ComputeOhms( stackup, aLayer, aWidthIU );
253	}
