255	
256	int IMPEDANCE_CALCULATOR::ComputeOhms( const BOARD_STACKUP& aStackup, PCB_LAYER_ID aLayer,
257	                                       int aWidthIU )
258	{
259	    CACHE_KEY key{ aLayer, aWidthIU };
260	    auto      it = m_cache.find( key );
261	
262	    if( it != m_cache.end() )
263	        return it->second;
264	
265	    const std::vector<BOARD_STACKUP_ITEM*>& layers = aStackup.GetList();
266	    const int signalIdx = findStackupCopperIndex( layers, aLayer );
267	
268	    wxLogTrace( IMPEDANCE_TRACE, "ComputeOhms: layer=%d width=%d signalIdx=%d stackupSize=%zu",
269	                (int) aLayer, aWidthIU, signalIdx, layers.size() );
270	
271	    if( signalIdx < 0 || aWidthIU <= 0 )
272	    {
273	        wxLogTrace( IMPEDANCE_TRACE,
274	                    "  → early-out (signalIdx<0 or width<=0).  Dumping stackup:" );
275	
276	        for( size_t i = 0; i < layers.size(); ++i )
277	        {
278	            BOARD_STACKUP_ITEM* item = layers[i];
279	            if( !item )
280	            {
281	                wxLogTrace( IMPEDANCE_TRACE, "    [%zu] null", i );
282	                continue;
283	            }
284	            wxLogTrace( IMPEDANCE_TRACE,
285	                        "    [%zu] type=%d enabled=%d brdLayerId=%d thickness=%d dk=%.3f",
286	                        i, (int) item->GetType(), (int) item->IsEnabled(),
287	                        (int) item->GetBrdLayerId(), item->GetThickness(),
288	                        item->HasEpsilonRValue() ? item->GetEpsilonR() : -1.0 );
289	        }
290	
291	        m_cache[key] = 0;
292	        return 0;
293	    }
294	
295	    BOARD_STACKUP_ITEM* signal           = layers[signalIdx];
296	    const double        signalThicknessM = signal->GetThickness() / 1e9;
297	    const double        widthM           = aWidthIU / 1e9;
298	
299	    int z0Ohms = 0;
300	
301	    if( aLayer == F_Cu || aLayer == B_Cu )
302	    {
303	        const DIELECTRIC_SPAN span = collectDielectricToReference( layers, signalIdx,
304	                                                                   ( aLayer == F_Cu ) ? +1 : -1 );
305	
306	        // Causal frequency dispersion: evaluate the bulk Dk/Df at the analysis frequency
307	        // from the datasheet values (specified at the Dk-measurement frequency).
308	        auto [dk, df] = djordjevicSarkar( span.dk, span.df, m_params.dkMeasurementFreqHz,
309	                                          m_params.frequencyHz );
310	
311	        wxLogTrace( IMPEDANCE_TRACE,
312	                    "  microstrip: signalT=%.6f widthM=%.6f heightM=%.6f dk0=%.3f→dk=%.3f df=%.4f",
313	                    signalThicknessM, widthM, span.heightM, span.dk, dk, df );
314	
315	        if( span.valid() )
316	            z0Ohms = analyseMicrostrip( widthM, signalThicknessM, span.heightM, dk, df,
317	                                        m_params );
318	    }
319	    else
320	    {
321	        const DIELECTRIC_SPAN top = collectDielectricToReference( layers, signalIdx, -1 );
322	        const DIELECTRIC_SPAN bot = collectDielectricToReference( layers, signalIdx, +1 );
323	
324	        wxLogTrace( IMPEDANCE_TRACE,
325	                    "  stripline: signalT=%.6f widthM=%.6f topH=%.6f topDk=%.3f "
326	                    "botH=%.6f botDk=%.3f",
327	                    signalThicknessM, widthM, top.heightM, top.dk, bot.heightM, bot.dk );
328	
329	        if( top.heightM > 0.0 && bot.heightM > 0.0 )
330	        {
331	            const double totalH = top.heightM + bot.heightM;
332	            const double dk0    = ( top.heightM * top.dk + bot.heightM * bot.dk ) / totalH;
333	            const double df0    = ( top.heightM * top.df + bot.heightM * bot.df ) / totalH;
334	
335	            // For stripline (pure TEM, no geometric dispersion in the model) the material
336	            // Dk(f) is the only frequency dependence of Z₀, so this is what makes the
337	            // reference-frequency setting actually move the inner-layer impedance.
338	            auto [dk, df] = djordjevicSarkar( dk0, df0, m_params.dkMeasurementFreqHz,
339	                                              m_params.frequencyHz );
340	
341	            z0Ohms = analyseStripline( widthM, signalThicknessM, top.heightM,
342	                                       bot.heightM, dk, df, m_params );
343	        }
344	    }
345	
346	    wxLogTrace( IMPEDANCE_TRACE, "  → z0=%d Ω", z0Ohms );
347	
348	    m_cache[key] = z0Ohms;
349	    return z0Ohms;
350	}
