    catch( const std::exception& )
    {
        continue;
    }

    if( z0 <= 0 || len <= 0 )
        continue;

    const int netCode = track->GetNetCode();
    weightedSum[netCode] += static_cast<int64_t>( z0 * len );
    totalLen[netCode] += static_cast<int64_t>( len );
}

