1727	{
1728	    if( !m_impedanceValue )
1729	        return;
1730	
1731	    BOARD* brd = m_frame->GetBoard();
1732	
1733	    if( !brd || !m_tracks )
1734	    {
1735	        m_impedanceValue->SetLabel( wxT( "—" ) );
1736	        return;
1737	    }
1738	
1739	    const std::optional<int> widthOpt = m_trackWidth.GetIntValue();
1740	    const int                layerSel = m_TrackLayerCtrl->GetLayerSelection();
1741	
1742	    if( !widthOpt || *widthOpt <= 0 || layerSel < 0 )
1743	    {
1744	        m_impedanceValue->SetLabel( wxT( "—" ) );
1745	        return;
1746	    }
1747	
1748	    const PCB_LAYER_ID layer = static_cast<PCB_LAYER_ID>( layerSel );
1749	
1750	    if( !IsCopperLayer( layer ) )
1751	    {
1752	        m_impedanceLabel->SetLabel( _( "Impedance Z₀:" ) );
1753	        m_impedanceValue->SetLabel( wxT( "—" ) );
1754	        return;
1755	    }
1756	
1757	    // If exactly one track is selected, use the model-aware calculation so a differential
1758	    // pair shows its differential impedance and a coplanar trace its CPWG impedance.  (These
1759	    // use the track's actual geometry / gap; the single-ended preview below tracks the width
1760	    // being edited for the common microstrip / stripline case.)
1761	    PCB_TRACK* singleTrack = nullptr;
1762	    int        trackCount  = 0;
1763	
1764	    for( EDA_ITEM* item : m_items )
1765	    {
1766	        if( PCB_TRACK* t = dynamic_cast<PCB_TRACK*>( item ) )
1767	        {
1768	            ++trackCount;
1769	            singleTrack = t;
1770	        }
1771	    }
1772	
1773	    if( trackCount == 1 && singleTrack )
1774	    {
1775	        const IMPEDANCE_RESULT imp = m_impedanceCalc.ComputeForTrack( brd, singleTrack );
1776	
1777	        if( imp.isDifferential() && imp.differentialOhms > 0 )
1778	        {
1779	            m_impedanceLabel->SetLabel( _( "Differential Z:" ) );
1780	            m_impedanceValue->SetLabel( wxString::Format( wxT( "%d" ), imp.differentialOhms ) );
1781	            return;
1782	        }
