void DIALOG_TRACK_VIA_PROPERTIES::updateImpedanceDisplay()
{
    if( !m_impedanceValue )
        return;

    BOARD* brd = m_frame->GetBoard();

    if( !brd || !m_tracks )
    {
        m_impedanceValue->SetLabel( wxT( "—" ) );
        return;
    }

    const std::optional<int> widthOpt = m_trackWidth.GetIntValue();
    const int                layerSel = m_TrackLayerCtrl->GetLayerSelection();

    if( !widthOpt || *widthOpt <= 0 || layerSel < 0 )
    {
        m_impedanceValue->SetLabel( wxT( "—" ) );
        return;
    }

    const PCB_LAYER_ID layer = static_cast<PCB_LAYER_ID>( layerSel );

    if( !IsCopperLayer( layer ) )
    {
        m_impedanceLabel->SetLabel( _( "Impedance Z₀:" ) );
        m_impedanceValue->SetLabel( wxT( "—" ) );
        return;
    }

    // If exactly one track is selected, use the model-aware calculation so a differential
    // pair shows its differential impedance and a coplanar trace its CPWG impedance.  (These
    // use the track's actual geometry / gap; the single-ended preview below tracks the width
    // being edited for the common microstrip / stripline case.)
    PCB_TRACK* singleTrack = nullptr;
    int        trackCount  = 0;

    for( EDA_ITEM* item : m_items )
    {
        if( PCB_TRACK* t = dynamic_cast<PCB_TRACK*>( item ) )
        {
            ++trackCount;
            singleTrack = t;
        }
    }

    if( trackCount == 1 && singleTrack )
    {
        const IMPEDANCE_RESULT imp = m_impedanceCalc.ComputeForTrack( brd, singleTrack );

        if( imp.isDifferential() && imp.differentialOhms > 0 )
        {
            m_impedanceLabel->SetLabel( _( "Differential Z:" ) );
            m_impedanceValue->SetLabel( wxString::Format( wxT( "%d" ), imp.differentialOhms ) );
            return;
        }

        if( ( imp.model == IMPEDANCE_MODEL::GROUNDED_COPLANAR
              || imp.model == IMPEDANCE_MODEL::COPLANAR )
            && imp.singleEndedOhms > 0 )
        {
            m_impedanceLabel->SetLabel( _( "Impedance Z₀ (CPW):" ) );
            m_impedanceValue->SetLabel( wxString::Format( wxT( "%d" ), imp.singleEndedOhms ) );
            return;
        }
    }

    m_impedanceLabel->SetLabel( _( "Impedance Z₀:" ) );

    const int z0 = m_impedanceCalc.ComputeOhms( brd, layer, *widthOpt );

    if( z0 <= 0 )
        m_impedanceValue->SetLabel( wxT( "—" ) );
    else
        m_impedanceValue->SetLabel( wxString::Format( wxT( "%d" ), z0 ) );
}


void DIALOG_TRACK_VIA_PROPERTIES::onViaSelect( wxCommandEvent& aEvent )
{
    VIA_DIMENSION* viaDimension = static_cast<VIA_DIMENSION*> ( aEvent.GetClientData() );

    m_viaDiameter.ChangeValue( viaDimension->m_Diameter );
    m_viaDrill.ChangeValue( viaDimension->m_Drill );

